#ifndef STUDIO_SHORTCUT_CATALOG_HPP
#include "keymap_data.hpp"
#define STUDIO_SHORTCUT_CATALOG_HPP
#include "shortcut_zh.hpp"
inline void loadDefaultShortcuts(ShortcutConfig& c){const uint32_t C=kModControl,S=kModShift,A=kModAlt;
    // Replace the early hand-copied context table with every original XML row.
    c.rows.erase(std::remove_if(c.rows.begin(),c.rows.end(),[](const ShortcutRow& r){return r.scope!=0;}),c.rows.end());
    for(size_t i=0;i<sizeof(keymap::hotkeys)/sizeof(keymap::hotkeys[0]);i++){auto& h=keymap::hotkeys[i];SHORT k=VkKeyScanW(W(h.key)[0]);uint32_t mask=(HIBYTE(k)&1?S:0)|(HIBYTE(k)&2?C:0)|(HIBYTE(k)&4?A:0);int scope=std::string(h.object)=="Atom"?2:std::string(h.object)=="Bond"?3:1;c.add("studio.hotkey."+std::to_string(i),((std::string(h.object)=="Atom"&&std::string(h.key)=="h")?std::string("氧/氮循环氢数；其他原子改为氢"):shortcutChinese(h))+" · "+h.key+(std::string(h.command)=="LABELTEXT"&&!(std::string(h.object)=="Atom"&&std::string(h.key)=="h")?" → "+std::string(h.value):""),(std::string(h.object)=="Atom"&&std::string(h.key)=="h")?"@cycleHydrogen":"@defaultHotkey",LOBYTE(k),mask,int(i),scope);}
    const std::map<std::string,std::string> known={{"bringToFront","@front"},{"sendToBack","@back"},{"cleanReaction","@cleanReaction"},{"cleanStructure","@clean"},{"2DTo3D","@clean3d"},{"convertNameToStructure","@nameToStructure"},{"convertStructureToName","@structureToName"},{"copyAsSMILES","@copySMILES"},{"copyAsHELM","@copyHELM"},{"copyAsMol","@copyMol"},{"copyAsMolV3000","@copyMol3000"},{"pasteAsSMILES","@pasteSMILES"},{"pasteAsMol","@pasteMol"},{"pasteAsHELM","@pasteHELM"},{"selectNextStructure","@nextStructure"},{"selectPreviousStructure","@previousStructure"},{"invertSelection","@invert"},{"toggleKekulization","@kekulize"},{"toggleStructurePerspective","@perspective"},{"print","@print"},{"quit","@quit"},{"window_Minimize","@minimize"},{"textAlignAutomatic","@autoLabel"},{"toggleCrosshairs","@crosshairs"},{"toggleRulers","@rulers"},{"addSplitter","@splitter"},{"showHelpContents","@help"}};
    size_t i=0;for(auto& m:keymap::menuKeys){std::string chord=m.chord,keyPart=chord;uint32_t mask=0;if(chord.find("Ctrl+")!=std::string::npos)mask|=C;if(chord.find("Shift+")!=std::string::npos)mask|=S;if(chord.find("Alt+")!=std::string::npos)mask|=A;auto pos=chord.find_last_of('+');if(pos!=std::string::npos)keyPart=chord.substr(pos+1);UINT key=keyPart=="Tab"?VK_TAB:keyPart=="delete"?VK_DELETE:keyPart.size()>1&&(keyPart[0]=='f'||keyPart[0]=='F')?VK_F1+atoi(keyPart.c_str()+1)-1:UINT(toupper(keyPart[0]));bool exists=false;for(auto& r:c.rows)if(r.scope==0&&r.defaults==key&&r.defaultModifiers==mask){exists=true;break;}if(!exists){auto f=known.find(m.command);c.add("studio.menu."+std::string(m.command),shortcutChinese(m),f!=known.end()?f->second:"@defaultCommand",key,mask,int(i));}++i;}
}
#endif
